package app.rwun;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.stream.Collectors;
import org.json.*;
/** Derived evidence, not a cached fitness/readiness score. */
final class CoachingMemory {
 private CoachingMemory(){}
 record Entry(String id,LocalDate date,int effort,int fatigue,boolean pain,double km,long seconds,String type,int stage,boolean complete,Boolean manageable){}
 static JSONObject data(RunStore s){JSONObject d=s.v103().optJSONObject("coaching");return d==null?new JSONObject():d;}
 static VoiceGuidance.Settings settings(RunStore s){return s.voiceSettings();}
 static VoiceGuidance.Settings settings(JSONObject d){JSONObject s=d.optJSONObject("settings");return s==null?VoiceGuidance.Settings.defaults():new VoiceGuidance.Settings(VoiceGuidance.Mode.valueOf(s.optString("mode")),s.optInt("interval"),s.optBoolean("splits"),s.optInt("heartLimit"));}
 static JSONObject settingsJson(VoiceGuidance.Settings s){try{return new JSONObject().put("mode",s.mode().name()).put("interval",s.checkSeconds()).put("splits",s.splits()).put("heartLimit",s.heartLimit());}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static int stage(RunStore s){return data(s).optInt("stage",0);}
 static List<Entry> entries(RunStore s){
  var out=new ArrayList<Entry>();JSONObject reviews=data(s).optJSONObject("reviews");if(reviews==null)return out;
  for(var r:s.runs()){JSONObject review=reviews.optJSONObject(r.sessionId());if(review!=null)out.add(entry(r.sessionId(),r.date(),r.rpe(),r.fatigue(),r.pain(),r.km(),r.seconds(),r.workoutType(),review));}
  JSONArray indoor=s.v103().optJSONArray("indoor");if(indoor!=null)for(int i=0;i<indoor.length();i++){JSONObject r=indoor.optJSONObject(i);String id="indoor:"+r.optString("id");if(r.optString("kind").equals("Run")&&r.isNull("km")&&reviews.optJSONObject(id)!=null)out.add(entry(id,r.optString("date"),r.optInt("effort"),r.optInt("fatigue"),r.optBoolean("pain"),0,r.optLong("seconds"),"Indoor run",reviews.optJSONObject(id)));}
  out.removeIf(e->e.date().isAfter(LocalDate.now()));out.sort(Comparator.comparing(Entry::date).thenComparing(Entry::id));return out;
 }
 private static Entry entry(String id,String date,int effort,int fatigue,boolean pain,double km,long seconds,String type,JSONObject r){return new Entry(id,LocalDate.parse(date),effort,fatigue,pain,km,seconds,type,r.optInt("stage",-1),r.optBoolean("complete"),r.has("manageable")?r.optBoolean("manageable"):null);}
 static String lesson(RunStore s){
  if(s.resting())return "Training is on hold. Review recovery before starting. A completed activity never clears this hold.";
  JSONObject check=data(s).optJSONObject("checkin");if(check!=null&&LocalDate.now().toString().equals(check.optString("date"))&&check.optInt("fatigue")>=4)return "Today's check-in reports high fatigue. Consider rest or an easier session. If you choose to continue, keep the effort comfortable and stop if running hurts.";
  var all=entries(s);if(all.isEmpty())return "We are establishing your baseline. Practise a comfortable, repeatable effort and record how it felt.";Entry last=all.get(all.size()-1);
  if(ChronoUnit.DAYS.between(last.date(),LocalDate.now())>=14)return "Your last reviewed run was at least two weeks ago. Review an easier return or repeat a manageable session. There is no catch-up mileage.";
  if(last.pain())return "Your latest reflection includes pain. Review recovery before planning another run.";
  if(last.effort()>=8||last.fatigue()>=4||Boolean.FALSE.equals(last.manageable()))return "Last time felt demanding. Start gently, keep the walking breaks and review an easier next session.";
  JSONObject pacing=data(s).optJSONObject("reviews").optJSONObject(last.id());if(pacing!=null&&pacing.optInt("paceSegments")>=3&&pacing.optDouble("lastPace")>pacing.optDouble("firstPace")*1.1)return "Your later recorded kilometre took longer than your first main-set kilometre. Practise a gentler start today. Terrain and conditions may explain the difference; no cause is assumed.";
  return Boolean.TRUE.equals(last.manageable())?"Last time you said the session was manageable. Repeat that controlled effort; progression is optional.":"Keep the next effort comfortable. Record whether it felt manageable so the next briefing can use your experience.";
 }
 static String briefing(RunStore s,String title){return lesson(s)+"\n\n"+CoachGuide.briefing(title,s.resting(),s.profile().seconds()>0);}
 static String progress(RunStore s){
  var all=entries(s);long days=all.stream().filter(e->!e.date().isBefore(LocalDate.now().minusDays(6))).map(Entry::date).distinct().count();String out="Reviewed running days in the last 7 days: "+days+". Walking totals remain separate.\n\n";
  if(all.isEmpty())return out+"No personal baseline yet. Imported totals without your reflection do not establish effort or readiness.";
  out+="Sessions you described as manageable without reported pain: "+all.stream().filter(e->Boolean.TRUE.equals(e.manageable())&&!e.pain()).count()+".\n\n";Entry last=all.get(all.size()-1);
  var matches=all.stream().filter(e->e.date().isBefore(last.date())&&!e.date().isBefore(last.date().minusDays(90))).filter(e->last.stage()>=0?e.stage()==last.stage()&&e.complete()&&last.complete():e.stage()<0&&e.type().equals(last.type())&&last.km()>0&&Math.abs(e.km()-last.km())<=last.km()*.1).collect(Collectors.toList());
  if(matches.isEmpty())out+="More comparable reviewed sessions are needed. Speed alone does not establish improvement.";else{Entry prev=matches.get(matches.size()-1);out+="Comparable session on "+prev.date()+": reported effort "+prev.effort()+"/10 → "+last.effort()+"/10 on "+last.date()+". "+(last.km()>0&&prev.km()>0?String.format(Locale.ROOT,"Distance %.2f → %.2f km. ",prev.km(),last.km()):"")+"Route, weather and terrain may differ. This comparison does not prove a fitness gain.";}
  JSONObject reviews=data(s).optJSONObject("reviews"),pacing=reviews.optJSONObject(last.id());if(pacing.optInt("paceSegments")>=2)out+="\n\nMain-set pacing: first kilometre "+PaceProfile.format(pacing.optDouble("firstPace"))+" → latest complete kilometre "+PaceProfile.format(pacing.optDouble("lastPace"))+" min/km. Variation across "+pacing.optInt("paceSegments")+" splits: "+Math.round(pacing.optDouble("variation")*100)+"%. GPS estimates; hills and conditions are not adjusted.";
  long longest=all.stream().filter(e->e.stage()>=0&&e.complete()).mapToLong(e->BeginnerProgramme.runSeconds(e.stage())).max().orElse(0);if(longest>0)out+="\n\nLongest prescribed running section in a completed beginner session: "+BeginnerProgramme.duration((int)longest)+". Indoor completion is self-reported; GPS cannot verify continuous running.";
  long rated=all.stream().filter(e->reviews.optJSONObject(e.id()).has("helpful")).count(),helpful=all.stream().filter(e->reviews.optJSONObject(e.id()).optBoolean("helpful")).count();if(rated>0)out+="\n\nYour voice feedback: helpful in "+helpful+" of "+rated+" answered running-session reviews. Adjust voice detail if cues are too frequent.";
  return out;
 }
 static String debrief(RunStore s){return lesson(s)+"\n\n"+progress(s)+"\n\nNext time: check how you feel, repeat a manageable effort and review proposed changes before applying them.";}
 static List<Entry> stageEvidence(RunStore s){var all=entries(s);var out=new ArrayList<Entry>();Set<LocalDate> days=new HashSet<>();for(int i=all.size()-1;i>=0;i--){Entry e=all.get(i);if(e.date().isBefore(LocalDate.now().minusDays(28)))break;if(e.pain()||e.effort()>=8||e.fatigue()>=4)return List.of();if(e.stage()!=stage(s))continue;if(!e.complete()||!Boolean.TRUE.equals(e.manageable())||e.effort()>5||e.fatigue()>3)break;if(days.add(e.date()))out.add(e);}return out;}
 static String progressionReason(RunStore s,int next){int stage=stage(s);if(s.resting())throw new IllegalStateException("Review the recovery hold first");if(next<0||next>=BeginnerProgramme.count()||Math.abs(next-stage)!=1)throw new IllegalArgumentException("Review one stage at a time");if(next<stage)return "You chose an easier stage. Reduce running sections while keeping a comfortable effort. This does not clear a recovery hold.";
  JSONObject check=data(s).optJSONObject("checkin");if(check!=null&&LocalDate.now().toString().equals(check.optString("date"))&&check.optInt("fatigue")>=4)throw new IllegalStateException("Today's check-in reports high fatigue. Repeat or review an easier session.");var evidence=stageEvidence(s);if(evidence.size()<3)throw new IllegalStateException("Complete and review three manageable sessions at this stage on separate days before considering progression.");if(ChronoUnit.DAYS.between(evidence.get(0).date(),LocalDate.now())>=14)throw new IllegalStateException("Review an easier return after time away before progressing");return "At least three completed sessions on separate days in the last 28 days, each manageable with effort ≤5/10, fatigue ≤3/5 and no pain. Dates: "+evidence.stream().map(e->e.date().toString()).limit(3).collect(Collectors.toList())+". This original software rule is not a readiness assessment.";}
 static String fingerprint(RunStore s){return fingerprint(s,data(s));}
 static String fingerprint(RunStore s,JSONObject data){try{JSONObject c=new JSONObject(data.toString());c.remove("changes");return hash(s.proposalFingerprint()+c+s.v103().optJSONArray("indoor"));}catch(JSONException e){throw new IllegalStateException(e);}}
 static String hash(String text){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static void validate(JSONObject d)throws Exception{
  for(String k:V1State.keys(d))if(!Set.of("version","stage","settings","reviews","changes","checkin").contains(k))throw new IllegalArgumentException("Unknown coaching setting");if(d.has("version"))V103Data.whole(d,"version",1,1);if(d.has("stage"))V103Data.whole(d,"stage",0,BeginnerProgramme.count()-1);
  if(d.has("settings")){JSONObject s=d.getJSONObject("settings");settings(d);for(String k:V1State.keys(s))if(!Set.of("mode","interval","splits","heartLimit").contains(k))throw new IllegalArgumentException("Unknown voice setting");V103Data.whole(s,"interval",180,900);V103Data.whole(s,"heartLimit",0,220);if(!(s.get("splits") instanceof Boolean))throw new IllegalArgumentException("Invalid split setting");}
  if(d.has("checkin")){JSONObject c=d.getJSONObject("checkin");LocalDate.parse(c.getString("date"));V103Data.whole(c,"fatigue",1,5);}
  if(d.has("reviews")){JSONObject reviews=d.getJSONObject("reviews");if(reviews.length()>10000)throw new IllegalArgumentException("Too many coaching reflections");for(String id:V1State.keys(reviews)){if(id.isEmpty()||id.length()>200)throw new IllegalArgumentException("Invalid reflection identity");JSONObject r=reviews.getJSONObject(id);for(String k:V1State.keys(r))if(!Set.of("stage","complete","manageable","helpful","paceSegments","firstPace","lastPace","variation").contains(k))throw new IllegalArgumentException("Invalid reflection field");V103Data.whole(r,"stage",-1,BeginnerProgramme.count()-1);for(String k:List.of("complete","manageable","helpful"))if(r.has(k)&&!(r.get(k) instanceof Boolean))throw new IllegalArgumentException("Invalid reflection answer");if(r.has("paceSegments")){V103Data.whole(r,"paceSegments",2,250);for(String k:List.of("firstPace","lastPace","variation")){double v=r.getDouble(k);if(!Double.isFinite(v)||v<0||v>180000)throw new IllegalArgumentException("Invalid pacing observation");}}}}
  if(d.has("changes")){JSONArray rows=d.getJSONArray("changes");if(rows.length()>1000)throw new IllegalArgumentException("Archive coaching changes before adding more");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!ids.add(r.getString("id"))||!Set.of("APPLY","UNDO").contains(r.getString("kind")))throw new IllegalArgumentException("Invalid stage change");V103Data.whole(r,"before",0,BeginnerProgramme.count()-1);V103Data.whole(r,"after",0,BeginnerProgramme.count()-1);V103Data.whole(r,"at",1,Long.MAX_VALUE);if(!r.getString("afterHash").matches("[a-f0-9]{64}")||r.getString("reason").length()>2000)throw new IllegalArgumentException("Invalid stage evidence");}}
 }
}
